ALTER TABLE "files" ADD CONSTRAINT "files_available_evidence_check" CHECK ("files"."storage_status" <> 'available' or ("files"."checksum_sha256" is not null and "files"."file_size_bytes" is not null and "files"."storage_verified_at" is not null)) NOT VALID;--> statement-breakpoint
ALTER TABLE "files" ADD CONSTRAINT "files_primary_namespace_check" CHECK ("files"."category" in ('patient-photos', 'documents', 'lab-results', 'branding', 'consents') and "files"."file_key" ~ ('^' || "files"."practice_id"::text || '/' || "files"."category" || '/[^/]+$') and "files"."file_url" = '/api/files/' || "files"."file_key") NOT VALID;--> statement-breakpoint
ALTER TABLE "files" ADD CONSTRAINT "files_patient_entity_consistency_check" CHECK ("files"."entity_type" is distinct from 'patient' or ("files"."patient_id" is not null and "files"."entity_id" is not null and "files"."entity_id" = "files"."patient_id")) NOT VALID;
